package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
class AssignmentRubricApiTest {
 SubmissionApiTest f;AssignmentRubricStore store;AssignmentRubricController api;
 @BeforeEach void setup(){f=new SubmissionApiTest();f.setup();store=mock(AssignmentRubricStore.class);api=new AssignmentRubricController(store,f.f.api,new SimpleMeterRegistry());}
 MockHttpServletRequest req(String method,String content){var r=f.req(method,content);r.removeHeader("If-Match");r.addHeader("If-Match","\"rb0\"");return r;}
 String input(){return "{\"assignmentVersion\":1,\"criteria\":[{\"criterionId\":null,\"title\":\"Clarity\",\"description\":\"\",\"maxPoints\":100}]}";}
 void status(int code,org.junit.jupiter.api.function.Executable action){assertEquals(code,assertThrows(ResponseStatusException.class,action).getStatusCode().value());}
 Object change(MockHttpServletRequest r)throws Exception{return api.change(f.f.group.toString(),f.study.toString(),f.assignment.toString(),r);}
 @Test void ownerOnlyWriteUsesAuthenticatedActorAndIndependentTag()throws Exception{var v=new AssignmentRubricStore.View(1,"DRAFT",null,true);when(store.change(eq(f.f.group),eq(f.f.space),eq(f.study),eq(f.assignment),eq(f.f.actor),eq(0L),any(),anyString())).thenReturn(v);var result=api.change(f.f.group.toString(),f.study.toString(),f.assignment.toString(),req("PUT",input()));assertEquals("\"rb0\"",result.getHeaders().getETag());assertEquals("no-store",result.getHeaders().getCacheControl());verify(store).change(eq(f.f.group),eq(f.f.space),eq(f.study),eq(f.assignment),eq(f.f.actor),eq(0L),eq(new AssignmentRubricInput(1,List.of(new AssignmentRubricInput.Item(null,"Clarity","",100)))),anyString());}
 @Test void memberAndViewerCannotMutateButMayReadSharedDraftAndHistory()throws Exception{for(var role:List.of("MEMBER","VIEWER")){f.f.role(role);status(403,()->change(req("PUT",input())));when(store.get(f.f.group,f.f.space,f.study,f.assignment,false)).thenReturn(new AssignmentRubricStore.View(1,"DRAFT",null,false));var r=req("GET",null);r.removeHeader("Origin");assertEquals(200,api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),r).getStatusCode().value());api.history(f.f.group.toString(),f.study.toString(),f.assignment.toString(),req("GET",null));}verify(store,times(2)).get(f.f.group,f.f.space,f.study,f.assignment,false);verify(store,times(2)).history(f.f.group,f.f.space,f.study,f.assignment,Long.MAX_VALUE,5);verify(store,never()).change(any(),any(),any(),any(),any(),anyLong(),any(),anyString());}
 @Test void exactJsonShapeVersionsTotalAndUnicodeAreRequired(){for(String v:List.of("{}",input()+" {}",input().replace("100","99"),input().replace("100","0"),input().replace("100","100.0"),input().replace("100","101"),input().replace("Clarity",""),input().replace("Clarity","x".repeat(101)),input().replace("Clarity","\\u0000"),input().replace("Clarity","\\ud800"),input().replace("assignmentVersion\":1","assignmentVersion\":1.0"),input().replace("assignmentVersion\":1","assignmentVersion\":0"),input().replace("{\"assignmentVersion\":1","{\"actorId\":\"forged\",\"assignmentVersion\":1"),input().replace("maxPoints\":100","maxPoints\":100,\"maxPoints\":100"))){status(400,()->change(req("PUT",v)));}verifyNoInteractions(store);}
 @Test void criteriaAreBoundedAndIdsAreCanonicalDuplicateFree(){String item="{\"criterionId\":null,\"title\":\"T\",\"description\":\"\",\"maxPoints\":10}";status(400,()->change(req("PUT","{\"assignmentVersion\":1,\"criteria\":["+String.join(",",Collections.nCopies(11,item))+"]}")));String withId=item.replace("null","\""+f.f.id+"\"").replace(":10",":50");status(400,()->change(req("PUT","{\"assignmentVersion\":1,\"criteria\":["+withId+","+withId+"]}")));status(400,()->change(req("PUT",input().replace("null","\"bad\""))));verifyNoInteractions(store);}
 @Test void strongTagExactQueryAndEmptyReadAreEnforced(){var missing=req("PUT",input());missing.removeHeader("If-Match");status(428,()->change(missing));for(String tag:List.of("*","W/\"rb0\"","\"sg1\"","\"rb01\"","\"rb9999999999999999999\"")){var r=req("PUT",input());r.removeHeader("If-Match");r.addHeader("If-Match",tag);status(400,()->change(r));}var duplicate=req("PUT",input());duplicate.addHeader("If-Match","\"rb0\"");status(400,()->change(duplicate));var query=req("GET",null);query.addParameter("actorId",f.f.actor.toString());status(400,()->api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),query));var limit=req("GET",null);limit.addParameter("limit","11");status(400,()->api.history(f.f.group.toString(),f.study.toString(),f.assignment.toString(),limit));status(400,()->api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),req("GET","{}")));verifyNoInteractions(store);}
 @Test void singletonCredentialSameOriginAndFreshMembershipAreRequired(){var duplicate=req("PUT",input());duplicate.addHeader("Cookie","__Host-brain_guest="+f.f.token);var insecure=req("PUT",input());insecure.setSecure(false);var cross=req("PUT",input());cross.removeHeader("Origin");cross.addHeader("Origin","https://elsewhere.invalid");for(var r:List.of(duplicate,insecure,cross))assertThrows(ResponseStatusException.class,()->change(r));when(f.f.auth.participation(any(),anyList(),anyString())).thenReturn(new GroupSpaceClient.Access(f.f.actor,"REGISTERED",List.of()));status(404,()->api.get(f.f.group.toString(),f.study.toString(),f.assignment.toString(),req("GET",null)));verifyNoInteractions(store);}
 @Test void byteLimitsAndSupplementaryUnicodeAreNotCharacterCountApproximations(){assertDoesNotThrow(()->AssignmentRubricInput.validate(new AssignmentRubricInput(1,List.of(new AssignmentRubricInput.Item(null,"😀".repeat(100),"가".repeat(682)+"ab",100)))));assertThrows(ResponseStatusException.class,()->AssignmentRubricInput.validate(new AssignmentRubricInput(1,List.of(new AssignmentRubricInput.Item(null,"T","가".repeat(683),100)))));status(413,()->change(req("PUT"," ".repeat(32769))));var type=req("PUT",input());type.setContentType("text/plain");status(415,()->change(type));verifyNoInteractions(store);}
}
